import 'package:flutter_test/flutter_test.dart';
import 'package:auren/features/itinerary_planner/domain/itinerary_planner.dart';
void main(){const p=ItineraryPlanner();test('prioritizes must-do items within capacity',(){final r=p.plan(const [ItineraryActivity(id:'museum',title:'Museum',durationMinutes:120,priority:2),ItineraryActivity(id:'train',title:'Train',durationMinutes:60,mustDo:true),ItineraryActivity(id:'cafe',title:'Cafe',durationMinutes:30)],availableMinutes:90);expect(r.scheduled.map((e)=>e.id),['train','cafe']);expect(r.usedMinutes,90);expect(r.unscheduled.single.id,'museum');});test('rejects negative capacity and ignores invalid items',(){expect(()=>p.plan(const [],availableMinutes:-1),throwsArgumentError);expect(p.plan(const [ItineraryActivity(id:'x',title:'bad',durationMinutes:0)],availableMinutes:10).scheduled,isEmpty);});}
